<script setup lang="ts">
import type { QTableColumn } from 'quasar';
import { useQuasar } from 'quasar';
import { computed, ref, shallowRef, watch } from 'vue';
import { applyNodeNetwork, createNodeNetwork, deleteNodeNetwork, getNodeNetwork, updateNodeNetwork, type PveNodeNetwork } from '@/api/host';
import TaskOutputDialog from '@/components/TaskOutputDialog.vue'; import UWindow from '@/components/UWindow.vue'; import { gettext } from '@/locale'; import { useSessionStore } from '@/stores/session';
type NetworkType='bridge'|'bond'|'OVSBridge'|'OVSBond'|'OVSIntPort'|'vlan'|'eth'; type Form=Record<string,string|boolean>&{type:NetworkType;iface:string;autostart:boolean};
const props=defineProps<{node:string}>();const $q=useQuasar();const session=useSessionStore();const rows=shallowRef<PveNodeNetwork[]>([]);const selected=shallowRef<PveNodeNetwork[]>([]);const changes=shallowRef('');const loading=shallowRef(false);const saving=shallowRef(false);const visible=shallowRef(false);const mode=shallowRef<'create'|'edit'>('create');const form=ref<Form>(empty());const taskVisible=shallowRef(false);const taskUpid=shallowRef('');const taskTitle=shallowRef('');
const canAudit=computed(()=>Boolean((session.caps as {nodes?:Record<string,unknown>}).nodes?.['Sys.Audit']));const canModify=computed(()=>Boolean((session.caps as {nodes?:Record<string,unknown>}).nodes?.['Sys.Modify']));const selectedRow=computed(()=>selected.value[0]);const editable=computed(()=>Boolean(selectedRow.value&&selectedRow.value.type!=='unknown'));const title=computed(()=>`${mode.value==='create'?gettext('Create'):gettext('Edit')}: ${gettext('Network Device')}`);const valid=computed(()=>Boolean(form.value.iface.trim()));
const columns:QTableColumn<PveNodeNetwork>[]=[{name:'iface',label:gettext('iface'),field:r=>name(r),align:'left',sortable:true},{name:'type',label:gettext('type'),field:r=>typeLabel(r.type),align:'left',sortable:true},{name:'active',label:gettext('active'),field:'active',align:'left'},{name:'autostart',label:gettext('autostart'),field:'autostart',align:'left'},{name:'method',label:gettext('method'),field:'method',align:'left'},{name:'method6',label:gettext('method6'),field:'method6',align:'left'},{name:'cidr',label:gettext('cidr'),field:'cidr',align:'left'},{name:'gateway',label:gettext('gateway'),field:'gateway',align:'left'},{name:'comments',label:gettext('Description'),field:'comments',align:'left'}];
let loadId=0;function str(row:Record<string,unknown>,key:string){const value=row[key];return value==null?'':String(value)}function bool(row:Record<string,unknown>,key:string){const value=row[key];return value===true||value===1||value==='1'}function name(row:PveNodeNetwork){const speed=Number(row.speed);return `${str(row,'iface')||'-'}${Number.isFinite(speed)&&speed>0?` (${speed/1000}Gb)`:''}`}function typeLabel(type:unknown){return ({bridge:gettext('Bridge'),bond:gettext('Bond'),OVSBridge:gettext('OVS Bridge'),OVSBond:gettext('OVS Bond'),OVSIntPort:gettext('OVS IntPort'),OVSPort:gettext('OVS IntPort'),vlan:gettext('VLAN'),eth:gettext('Physical Interface')} as Record<string,string>)[String(type)]||String(type||'-')}
function next(type:NetworkType){const prefix=type==='bond'||type==='OVSBond'?'bond':type==='vlan'?'vlan':type==='eth'?'eth':'vmbr';const used=new Set(rows.value.map(row=>str(row,'iface')));let index=0;while(used.has(`${prefix}${index}`))index++;return `${prefix}${index}`}function empty(type:NetworkType='bridge'):Form{return{type,iface:next(type),autostart:true,method:'',method6:'',cidr:'',gateway:'',cidr6:'',gateway6:'',comments:'',bridge_ports:'',bridge_stp:false,bridge_fd:'',bridge_vlan_aware:false,bond_slaves:'',bond_mode:'',vlan_raw_device:'',ovs_ports:'',ovs_bonds:'',ovs_bridge:'',ovs_options:''}}
async function load(){const node=props.node,id=++loadId;if(!node||!canAudit.value){rows.value=[];changes.value='';return;}loading.value=true;try{const response=await getNodeNetwork(node,{_dc:Date.now()});if(id!==loadId||node!==props.node)return;rows.value=response.data||[];changes.value=response.changes||'';const iface=str(selectedRow.value||{},'iface');selected.value=iface?rows.value.filter(row=>str(row,'iface')===iface):[]}finally{if(id===loadId)loading.value=false}}
function open(type:NetworkType='bridge'){mode.value='create';form.value=empty(type);visible.value=true}function edit(){const row=selectedRow.value;if(!row)return;const type=(row.type==='OVSPort'?'OVSIntPort':row.type) as NetworkType;mode.value='edit';form.value={...empty(type),...Object.fromEntries(Object.keys(empty(type)).map(key=>[key,key==='type'?type:key==='autostart'?bool(row,key):str(row,key)])),cidr:str(row,'cidr')||str(row,'address'),cidr6:str(row,'cidr6')||str(row,'address6')};visible.value=true}
function payload(){const data:Record<string,unknown>={};for(const [key,value] of Object.entries(form.value)){if(key==='type')data[key]=value;else if(typeof value==='boolean')data[key]=value?1:0;else data[key]=value.trim()}return data}async function task(upid?:string,label?:string){if(upid?.startsWith('UPID:')){taskUpid.value=upid;taskTitle.value=label||gettext('Network');taskVisible.value=true}else await load()}async function save(){if(!props.node||!valid.value)return;saving.value=true;try{const response=mode.value==='create'?await createNodeNetwork(props.node,payload()):await updateNodeNetwork(props.node,form.value.iface,payload());visible.value=false;await task(response.data,mode.value==='create'?gettext('Create Network Device'):gettext('Save Network Configuration'))}finally{saving.value=false}}
function remove(){const iface=str(selectedRow.value||{},'iface');if(!iface)return;$q.dialog({title:gettext('Confirm'),message:gettext('Are you sure to remove [%s]?').replace('%s',iface),cancel:true,persistent:true}).onOk(()=>void(async()=>{saving.value=true;try{const response=await deleteNodeNetwork(props.node,iface);await task(response.data,gettext('Remove Network Device'))}finally{saving.value=false}})())}function apply(){if(!changes.value)return;$q.dialog({title:gettext('Confirm'),message:`${gettext('Do you want to apply pending network changes')} ?`,cancel:true,persistent:true}).onOk(()=>void(async()=>{saving.value=true;try{const response=await applyNodeNetwork(props.node);await task(response.data,gettext('Apply Network Configuration'))}finally{saving.value=false}})())}watch([()=>props.node,canAudit],()=>{visible.value=false;void load()},{immediate:true});
</script>
<template><q-table flat row-key="iface" selection="single" hide-selected-banner table-header-class="u-table-header" :rows="rows" :columns="columns" :loading="loading" :selected="selected" :rows-per-page-options="[0]" :no-data-label="gettext('no record can be found')" table-style="max-width:100%;overflow-x:auto" @update:selected="selected=[...$event]"><template #top><div class="row full-width items-center q-gutter-sm"><q-btn-dropdown no-caps outline size="12px" color="primary" class="u-button" :disable="!canModify" :label="gettext('Create')"><q-list dense><q-item v-for="option in [{label:gettext('Bridge'),value:'bridge'},{label:gettext('Bond'),value:'bond'},{label:gettext('OVS Bridge'),value:'OVSBridge'},{label:gettext('OVS Bond'),value:'OVSBond'},{label:gettext('OVS IntPort'),value:'OVSIntPort'},{label:gettext('VLAN'),value:'vlan'},{label:gettext('Physical Interface'),value:'eth'}]" :key="option.value" v-close-popup clickable @click="open(option.value as NetworkType)"><q-item-section>{{option.label}}</q-item-section></q-item></q-list></q-btn-dropdown><q-btn no-caps outline size="12px" class="u-button" :disable="!editable||!canModify" :loading="saving" :label="gettext('Edit')" @click="edit"/><q-btn no-caps outline size="12px" class="u-button" :disable="!selectedRow||!canModify" :loading="saving" :label="gettext('Remove')" @click="remove"/><q-btn no-caps outline size="12px" color="primary" class="u-button" :loading="loading" :label="gettext('Reload')" @click="load"/><q-btn no-caps outline size="12px" class="u-button" :disable="!changes||!canModify" :loading="saving" :label="gettext('Apply Configuration')" @click="apply"/><q-space/><q-badge v-if="changes" color="red">{{gettext('Pending changes')}}</q-badge></div></template><template #body-cell-active="scope"><q-td :props="scope"><q-badge :color="scope.value?'green':'grey'" :label="scope.value?gettext('Active'):'-'"/></q-td></template></q-table><pre v-if="changes" class="pending">{{changes}}</pre><q-dialog v-model="visible" persistent transition-show="scale" transition-hide="scale"><UWindow :title="title" width="900px" :loading="saving"><q-form class="q-pa-md u-dense" @submit.prevent="save"><div class="u-border q-pa-md row q-col-gutter-lg"><div v-for="field in ['iface','method','method6','cidr','gateway','cidr6','gateway6','comments','bridge_ports','bridge_fd','bond_slaves','bond_mode','vlan_raw_device','ovs_ports','ovs_bonds','ovs_bridge','ovs_options']" :key="field" class="col-6"><q-input v-model="form[field] as string" dense outlined :disable="field==='iface'&&mode==='edit'" :label="gettext(field)"/></div><div class="col-6"><q-checkbox v-model="form.autostart" dense :label="gettext('autostart')"/></div></div></q-form><template #foot><q-btn v-close-popup no-caps outline size="12px" class="u-button" :label="gettext('Cancel')"/><q-btn no-caps flat size="12px" class="bg-primary text-grey-1 u-button" :disable="!valid||saving" :label="mode==='create'?gettext('Create'):gettext('Save')" @click="save"/></template></UWindow></q-dialog><TaskOutputDialog v-model="taskVisible" :node="props.node" :upid="taskUpid" :title="taskTitle" @finished="load"/></template>
<style scoped>.pending{max-height:180px;margin:0;padding:12px;overflow:auto;border:1px solid #dfe1e6;border-top:0;background:#f7f9fb;color:#333;font-size:12px;line-height:1.6;white-space:pre-wrap;word-break:break-word}</style>
